   347  int
   348  sc_pkcs15_pubkey_from_cert(struct sc_context *ctx,
   349                  struct sc_pkcs15_der *cert_blob, struct sc_pkcs15_pubkey **out)
   350  {
   351          int rv;
   352          struct sc_pkcs15_cert * cert;
   353
   354          cert =  calloc(1, sizeof(struct sc_pkcs15_cert));
   355          if (cert == NULL)
   356                  return SC_ERROR_OUT_OF_MEMORY;
   357
   358          rv = parse_x509_cert(ctx, cert_blob, cert);
   359
   360          *out = cert->key;
   361          cert->key = NULL;
   362          sc_pkcs15_free_certificate(cert);
   363
   364          LOG_FUNC_RETURN(ctx, rv);
   365  }
